const body = pm.response.json();

pm.test("El servidor responde 200 OK", function () {
    pm.response.to.have.status(200);
});

pm.test("El backend reporta estado UP", function () {
    pm.expect(body.status).to.eql("UP");
});

pm.test("Está conectado a la base petcare_db", function () {
    pm.expect(body.database).to.eql("petcare_db");
});

pm.test("Incluye los contadores de usuarios y mascotas", function () {
    pm.expect(body).to.have.property("usersCount");
    pm.expect(body).to.have.property("petsCount");
});

pm.test("Responde en menos de 1 segundo", function () {
    pm.expect(pm.response.responseTime).to.be.below(1000);
});

const body = pm.response.json();

pm.test("Responde 200 OK", function () {
    pm.response.to.have.status(200);
});

pm.test("La respuesta es una lista", function () {
    pm.expect(body).to.be.an("array");
});

pm.test("Todas las mascotas están activas", function () {
    body.forEach(pet => pm.expect(pet.status).to.eql("ACTIVE"));
});

pm.test("Cada mascota tiene nombre y especie", function () {
    body.forEach(pet => {
        pm.expect(pet.name).to.be.a("string").and.not.empty;
        pm.expect(pet.species).to.be.a("string").and.not.empty;
    });
});

const body = pm.response.json();

pm.test("Responde 201 Created", function () {
    pm.response.to.have.status(201);
});

pm.test("Devuelve el id generado", function () {
    pm.expect(body.id).to.be.a("number");
});

pm.test("Incluye el encabezado Location", function () {
    pm.expect(pm.response.headers.get("Location")).to.include("/api/pets/" + body.id);
});

pm.test("La mascota se crea activa", function () {
    pm.expect(body.status).to.eql("ACTIVE");
});

pm.test("Guarda los datos enviados", function () {
    pm.expect(body.name).to.eql("Coco");
    pm.expect(body.species).to.eql("Conejo");
});

